#!/usr/bin/env node
/**
 * gen-backlog-tasks.mjs — BACKLOG.md → lib/tasks/backlog.tasks.mjs
 *
 * Precomputes the parsed rows at build time as an ESM module (not JSON) so the
 * /api/tasks-import serverless function imports it natively on Vercel — a plain
 * `.mjs` import needs no `type: json` attribute and no bundler inlining, exactly
 * like the other lib/*.mjs the function already imports. Regenerated by
 * ensure-ops-data on every build/typecheck, so it never drifts from BACKLOG.md.
 */

import { readFileSync, writeFileSync, mkdirSync } from 'node:fs';
import { resolve, dirname } from 'node:path';
import { fileURLToPath } from 'node:url';
import { parseBacklog } from '../lib/tasks/backlog.mjs';

const ROOT = resolve(dirname(fileURLToPath(import.meta.url)), '..');
const OUT = resolve(ROOT, 'lib/tasks/backlog.tasks.mjs');

const md = readFileSync(resolve(ROOT, 'BACKLOG.md'), 'utf8');
const rows = parseBacklog(md);
mkdirSync(dirname(OUT), { recursive: true });
writeFileSync(
  OUT,
  `// GENERATED by scripts/gen-backlog-tasks.mjs from BACKLOG.md — do not edit.\n` +
    `export const backlogTasks = ${JSON.stringify(rows, null, 2)};\n`,
);
console.log(`[gen-backlog-tasks] wrote ${rows.length} rows → lib/tasks/backlog.tasks.mjs`);
